<script setup>
import {actions,actionCN} from '../data/system'
import {action,view,level,filtered} from '../composables/useArchive'
defineEmits(['about','relations'])
</script>
<template><div class="reservoir-controls"><div class="sidebar-label">LEVEL / 网格密度</div><div class="density-number">{{level}}<small>%</small></div><input class="density-slider" type="range" min="0" max="100" step="1" v-model.number="level" aria-label="LEVEL 网格密度"/><div class="density-scale mono"><span>疏 / LOW</span><span>密 / HIGH</span></div><div class="density-matrix" aria-hidden="true"><i v-for="n in 60" :key="n" :class="{filled:n<=level*.6}"></i></div><p class="density-note">{{view==='GRID'?'低密度：少而大；高密度：多而小。':'密度设置保留，返回网格时生效。'}}<small>IMAGE SCALE × OBJECT COUNT</small></p><section class="action-controls"><div class="sidebar-label">RESERVOIR ACTION<span>蓄水动作</span></div><p>仅作用于 A 功能原型与 B 空间原型<small>PROTOTYPE MOTION ONLY</small></p><div class="action-options"><button v-for="(a,i) in actions" :key="a" @click="action=a" :aria-pressed="action===a" :class="{selected:action===a}" :disabled="!['MAP','DEPTH'].includes(view)||!filtered.some(o=>o.actionEligible)"><span>{{a}}</span><span>{{actionCN[i]}}</span></button></div><p v-if="!['MAP','DEPTH'].includes(view)" class="action-hint">切换三维视图以运行动作。<small>ACTIVATE IN MAP / DEPTH</small></p><p v-if="['MAP','DEPTH'].includes(view)&&!filtered.some(o=>o.actionEligible)" class="action-hint">当前分类不参与动作。<small>NO ELIGIBLE PROTOTYPES</small></p></section><footer class="control-footer"><span class="mono">{{filtered.length}} OBJECTS / 当前档案</span><button @click="$emit('relations')">RELATIONS / 交叉关系 ↓</button><button @click="$emit('about')">SYSTEM INFO / 系统说明 ↗</button></footer></div></template>
